 import pandas as pd
import os
import re

input_path = r"C:/Users/darpa/Downloads/Resume_Projects/AI Data Agent/data/etl_eval/input/payments_messy.csv"
output_folder = r"C:/Users/darpa/Downloads/Resume_Projects/AI Data Agent/data/etl_eval/output/h06"
os.makedirs(output_folder, exist_ok=True)

df = pd.read_csv(input_path)

def clean_amount(val):
    if pd.isna(val):
        return None
    s = str(val)
    s = s.replace("CAD", "").replace("$", "").replace(",", "").strip()
    try:
        return float(s)
    except ValueError:
        return None

df["amount_cad"] = df["amount"].apply(clean_amount)

def parse_date(val):
    if pd.isna(val):
        return None
    s = str(val).strip()
    if "/" in s:
        dt = pd.to_datetime(s, format="%m/%d/%Y", errors="coerce")
    else:
        dt = pd.to_datetime(s, errors="coerce")
    if pd.isna(dt):
        return None
    return dt.strftime("%Y-%m-%d")

df["paid_on"] = df["paid_on"].apply(parse_date)

df = df.drop(columns=["amount"])

output_file = os.path.join(output_folder, "payments_cleaned.parquet")
df.to_parquet(output_file, index=False) 

